def git(*args):
    return subprocess.run(["git", *args], capture_output=True, text=True)


def main():
    if not (pathlib.Path.cwd() / "port/tools/android.py").exists():
        sys.exit("Run this from the root of the DragonRage repository.")
    data = gzip.decompress(base64.b64decode("".join(PATCH.split())))
    with tempfile.NamedTemporaryFile("wb", suffix=".patch", delete=False) as f:
        f.write(data)
        path = f.name
    for extra in ([], ["--3way"]):
        if git("apply", "--check", "--whitespace=nowarn", *extra, path).returncode == 0:
            r = git("apply", "--whitespace=nowarn", *extra, path)
            print(r.stdout + r.stderr)
            print("Patch applied. Next:")
            print("  python3 port/tools/android.py")
            print("  cd android; ./gradlew assembleRelease; cd ..")
            print("  adb install -r android/app/build/outputs/apk/release/app-release.apk")
            return
    print(git("apply", "--check", "--whitespace=nowarn", path).stderr[:3000])
    sys.exit("The patch does not apply: it is made for main at bbd4c2b (Dragon Rage 0.5.0). Nothing was changed.")


if __name__ == "__main__":
    main()
